// V-通用Banner
import "./index.less";
import CommonCarousel from "./common-carousel";

(function () {
  document.addEventListener('DOMContentLoaded', () => {
    const commonBanners = document.querySelectorAll('.block-common-banner');
    if (commonBanners.length === 0) return;

    commonBanners.forEach(item => {
      const bannerWrapper = item.querySelector('.common-banner-wrapper');
      const items = bannerWrapper.querySelectorAll('.swiper-slide');

      if (items.length === 0) {
        // 无banner，则隐藏（未配置或banner时效到期）
        item.classList.add('hidden');
        return;
      }

      // ✅ 移除第一张 slide 所有图片的 loading 属性
      const firstSlideImgs = items[0].querySelectorAll('img');
      firstSlideImgs.forEach(img => img.removeAttribute('loading'));

      if (items.length > 1) {
        item.querySelectorAll('.swiper-arrow').forEach(arrow => arrow.classList.add('lg:flex', 'mb-flex'));

        const itemId = item.getAttribute('id');
        const loop = bannerWrapper.getAttribute('data-loop') === 'true' ? true : false;
        const autoplay = bannerWrapper.getAttribute('data-autoplay') === 'true' ? true : false;
        const delay = Number(bannerWrapper.getAttribute('data-delay')) || 5;
        new CommonCarousel({
          elName: `#${itemId}`,
          loop: loop,
          autoplay: autoplay,
          delay: delay,
          PCSlidesPerView: 1,
          PCSpaceBetween: 0,
          MBSpaceBetween: 0,
          MBSlidesPerView: 1
        })
      }
    })
  })
})();
