// 通用轮播
export default class CommonCarousel {
  constructor(obj) {
    this.DOM = {
      elName: obj.elName, 						// 对象class名
      loop: obj.loop || false, 					// 是否循环
      autoplay: obj.autoplay || false, 			// 是否自动轮播
      delay: obj.delay || 5, 					// 单个轮播图停留时长
      PCSlidesPerView: obj.PCSlidesPerView || 3, 	// PC端每屏展示几个Slide
      PCSpaceBetween: obj.PCSpaceBetween || 0,	// PC端左右间距
      MBSlidesPerView: obj.MBSlidesPerView || 1, 	// MB端每屏展示几个Slide
      MBSpaceBetween: obj.MBSpaceBetween || 0, 	// MB端左右间距
    };

    this.initParams();

    this.init();
  }

  // 初始化参数
  initParams() {
    const windowWidth = window.innerWidth;
    if (windowWidth < 1024) {
      const spaceBetweenVal = (windowWidth * this.DOM.MBSpaceBetween) / 750;
      this.dataJson = {
        slidesPerView: this.DOM.MBSlidesPerView,
        spaceBetween: spaceBetweenVal,
        effect: 'slide'
      };
    } else {
      this.dataJson = {
        slidesPerView: this.DOM.PCSlidesPerView,
        spaceBetween: this.DOM.PCSpaceBetween,
        effect: 'slide'
      };
    }
  }

  init() {
    const that = this;
    this.swiper = new Swiper(`${this.DOM.elName} .swiper`, {
      loop: this.DOM.loop,
      slidesPerView: this.dataJson.slidesPerView,
      centeredSlides: false,
      spaceBetween: this.dataJson.spaceBetween,
      effect: this.dataJson.effect,
      followFinger: false,
      watchSlidesProgress: true,
      watchSlidesVisibility: true,
      observer: true, // 开启动态检查器，监测swiper和slide
      observeParents: true, // 监测Swiper 的祖/父元素
      lazy: {
        loadPrevNext: true,
        loadPrevNextAmount: 1
      },
      autoplay: this.DOM.autoplay ? {
        delay: this.DOM.delay * 1000,
        stopOnLastSlide: false,
        disableOnInteraction: false,
      } : false,
      navigation: {
        nextEl: `${this.DOM.elName} .swiper-button-next`,
        prevEl: `${this.DOM.elName} .swiper-button-prev`,
      },
      pagination: {
        el: `${this.DOM.elName} .slideshow-pagination`,
        clickable: true,
        bulletClass: 'slideshow-pagination-item',
        bulletActiveClass: 'active pagination-active',
        clickableClass: 'slideshow-pagination-clickable',
        modifierClass: 'slideshow-pagination-',
        renderBullet(index) {
          let paginationItem = '<span class="slideshow-pagination-item">';
          paginationItem = (index <= 8) ? `${paginationItem}<span class="pagination-separator"><span class="pagination-separator-loader"></span></span>` : paginationItem;
          paginationItem += '</span>';
          return paginationItem;
        }
      },
      on: {
        slideChangeTransitionEnd: function () {
          // 防止轮播懒加载白屏
          const curSlide = Array.from(this.slides).filter((it) => it.classList.contains("swiper-slide-active"));
          const curImg = curSlide[0].querySelector("img.banner-img");
          if (curImg) {
            curImg.classList.remove("lazyloading");
            curImg.classList.add("lazyloaded");
          }

          // 暂停所有视频。播放当前视频
          Array.from(this.slides).filter((it) => {
            const video = it.querySelector("viewport-video") || it.querySelector("viewport-youtube")
            if (it.classList.contains("swiper-slide-active")) {
              video && video.play()
            } else {
              video && video.pause()
            }
          })
        },
        paginationUpdate: function (swiper, paginationEl) {
          that.pageAnimatePagination(paginationEl);
        }
      }
    });
  }

  // 分页器进度动画
  pageAnimatePagination(paginationEl) {
    // 仅启用自动轮播时生效
    if (this.DOM.autoplay) {
      window.Jackery.Utils.swiperAnimatePagination(paginationEl, this.DOM.autoplay, this.DOM.delay);
    }
  }
}
